def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1

    # The boundary color appears on two opposite edges.
    boundary = None
    for v in counts:
        if v == bg:
            continue
        if (any(grid[0][c] == v for c in range(w)) and any(grid[h-1][c] == v for c in range(w))) or \
           (any(grid[r][0] == v for r in range(h)) and any(grid[r][w-1] == v for r in range(h))):
            boundary = v
            break
    if boundary is None:
        return [row[:] for row in grid]

    markers = [(r, c, v) for r in range(h) for c in range(w)
               if grid[r][c] not in (bg, boundary)]
    if not markers:
        return [row[:] for row in grid]
    r, c, color = markers[0]
    out = [row[:] for row in grid]

    # Find the two boundary runs and the marker's corresponding run.
    if any(grid[0][x] == boundary for x in range(w)) and any(grid[h-1][x] == boundary for x in range(w)):
        def run(row):
            xs = [x for x in range(w) if grid[row][x] == boundary]
            return min(xs), max(xs)
        top, bottom = run(0), run(h-1)
        if top[0] <= c <= top[1]:
            near, far, nearpos, farpos = 0, h-1, top, bottom
            toward = -1
        else:
            near, far, nearpos, farpos = h-1, 0, bottom, top
            toward = 1
        # Marker rays toward its aligned boundary.
        for rr in range(r + toward, near + toward, toward):
            out[rr][c] = color
        out[r][c] = 4
        mapped = c + (farpos[0] - nearpos[0])
        mapped = max(0, min(w-1, mapped))
        step = 1 if far == 0 else -1
        for rr in range(far + step, h if step == 1 else -1, step):
            if out[rr][mapped] != boundary:
                out[rr][mapped] = color
    else:
        def run(col):
            ys = [y for y in range(h) if grid[y][col] == boundary]
            return min(ys), max(ys)
        left, right = run(0), run(w-1)
        if left[0] <= r <= left[1]:
            near, far, nearpos, farpos = 0, w-1, left, right
            toward = -1
        else:
            near, far, nearpos, farpos = w-1, 0, right, left
            toward = 1
        for cc in range(c + toward, near + toward, toward):
            out[r][cc] = color
        out[r][c] = 4
        mapped = r + (farpos[0] - nearpos[0])
        mapped = max(0, min(h-1, mapped))
        step = 1 if far == 0 else -1
        for cc in range(far + step, w if step == 1 else -1, step):
            if out[mapped][cc] != boundary:
                out[mapped][cc] = color
    return out
